def test_read_requirements_txt(tmp_path: Path) -> None:
    """Test reading package names from requirements.txt."""
    content = """\
# Comment
requests>=2.0
-r sub-requirements.txt
--requirement other.txt
-c constraints.txt
urllib3
"""
    path = tmp_path / "requirements.txt"
    path.write_text(content, encoding="utf-8")

    assert PackageMetadataReader._read_requirements_txt(path) == {
        "requests",
        "urllib3",
    }


def test_read_requirements_txt_missing(tmp_path: Path) -> None:
    """Test missing requirements files return an empty set."""
    path = tmp_path / "missing_requirements.txt"

    assert PackageMetadataReader._read_requirements_txt(path) == set()


