def test_read_all_files(tmp_path: Path) -> None:
    (tmp_path / "pyproject.toml").write_text(
        '[project]\ndependencies = ["requests"]', encoding="utf-8"
    )
    (tmp_path / "requirements.txt").write_text("flask\n", encoding="utf-8")
    (tmp_path / "requirements-dev.txt").write_text("pytest\n", encoding="utf-8")
    (tmp_path / "setup.cfg").write_text(
        "[options]\ninstall_requires = numpy", encoding="utf-8"
    )
    (tmp_path / "setup.py").write_text(
        'setup(install_requires=["scipy"])', encoding="utf-8"
    )
    (tmp_path / "Pipfile").write_text("[packages]\ntabulate = '*'", encoding="utf-8")

    deps = PackageMetadataReader.read(tmp_path)
    assert deps == {"requests", "flask", "pytest", "numpy", "scipy", "tabulate"}


